17|typedef struct {
18|	lzma_next_coder next;
19|
20|	enum {
21|		SEQ_PROPERTIES,
22|		SEQ_DICTIONARY_SIZE,
23|		SEQ_UNCOMPRESSED_SIZE,
24|		SEQ_CODER_INIT,
25|		SEQ_CODE,
