137|		coder->pos = 0;
138|		coder->sequence = SEQ_CODER_INIT;
139|		FALLTHROUGH;
140|
141|	case SEQ_CODER_INIT: {
142|		if (coder->memusage > coder->memlimit)
143|			return LZMA_MEMLIMIT_ERROR;
