145|		lzma_filter_info filters[2] = {
146|			{
147|				.id = LZMA_FILTER_LZMA1EXT,
148|				.init = &lzma_lzma_decoder_init,
149|				.options = &coder->options,
150|			}, {
151|				.init = NULL,
152|			}
153|		};
154|
155|		return_if_error(lzma_next_filter_init(&coder->next,
